fn m0(
    t: &[u16],
    pos: usize,
    bts: &mut Vec<aot::Bt>,
    steps: &mut aot::Steps,
    captures: &mut [Option<core::ops::Range<usize>>],
) -> Option<usize> {
    let mut s = aot::State::<0, 0>::new(bts, steps);
    let end = m0_0(t, pos, &mut s)?;
    s.captures(captures);
    Some(end)
}

fn m0_0(t: &[u16], mut pos: usize, s: &mut aot::State<'_, 0, 0>) -> Option<usize> {
    let base = s.bts.len();
    let mut label = 0u32;
    'run: loop {
        'fail: {
            match label {
                0 => {
                    if !t.get(pos).is_some_and(|&u| matches!(u, 0x22)) {
                        label = 1;
                        continue 'run;
                    }
                    if t.get(pos).is_some_and(|&u| matches!(u, 0x3e | 0xab)) {
                        s.bts.push(aot::Bt::Position { label: 1, pos });
                    }
                    match t.get(pos) {
                        Some(&u) if matches!(u, 0x22) => pos += 1,
                        _ => break 'fail,
                    }
                    label = 3;
                    continue 'run;
                }
                1 => {
                    if !t.get(pos).is_some_and(|&u| matches!(u, 0xab)) {
                        label = 2;
                        continue 'run;
                    }
                    if t.get(pos).is_some_and(|&u| matches!(u, 0x3e)) {
                        s.bts.push(aot::Bt::Position { label: 2, pos });
                    }
                    match t.get(pos) {
                        Some(&u) if matches!(u, 0xab) => pos += 1,
                        _ => break 'fail,
                    }
                    match t.get(pos) {
                        Some(&u) if matches!(u, 0x3c) => pos += 1,
                        _ => break 'fail,
                    }
                    label = 3;
                    continue 'run;
                }
                2 => {
                    match t.get(pos) {
                        Some(&u) if matches!(u, 0x3e) => pos += 1,
                        _ => break 'fail,
                    }
                    match t.get(pos) {
                        Some(&u) if matches!(u, 0xab) => pos += 1,
                        _ => break 'fail,
                    }
                    match t.get(pos) {
                        Some(&u) if matches!(u, 0x29 | 0x2c | 0x2e | 0x3a..=0x3b) => pos += 1,
                        _ => break 'fail,
                    }
                    label = 3;
                    continue 'run;
                }
                3 => {
                    s.bts.truncate(base);
                    return Some(pos);
                }
                _ => unreachable!(),
            }
        }
        (label, pos) = s.backtrack::<true, true>(t, base)?;
    }
}

